<script setup lang="ts">
import { computed,onMounted,onUnmounted,ref,watch } from 'vue'
import { useRoute } from 'vue-router'
import { workbenchApi,type Plant } from '../workbench/api'
import StateNotice from '../components/StateNotice.vue'
import ResearchContextBar from '../components/ResearchContextBar.vue'
import PlantMediaGallery from '../components/PlantMediaGallery.vue'
import StatusIndicator from '../components/StatusIndicator.vue'
import UiIcon from '../components/UiIcon.vue'
import type { AgentContext } from '../assistant/api'
import '../styles/plant-detail.css'
type PlantSourceView={names:{name_text:string;name_role:string;language_tag:string;review_state:string;source_url?:string;source_version?:string;authority_taxon_id?:string;match_method?:string;confidence?:string;queried_at?:string;name_source_sha256?:string;name_source_sheet?:string;name_source_row?:number}[];taxonomy:{id:string;canonical_name:string;taxon_rank:string;identity_state:string}[];records:{id:string;pipeline:string;knowledge_confidence:string|null;normalized_payload:unknown;source_id:string|number;locator:unknown}[];notice:string}
type PlantRich=Plant&Record<string,unknown>&{morphology?:string|null;distribution?:string|null;familyName?:string|null;genusName?:string|null;author?:string|null}
const route=useRoute(),plant=ref<PlantRich|null>(null),node=ref<string|null>(null),sources=ref<{sourceId:string|number;displayLabel:string;sha256?:string;licenseState?:string}[]>([]),detail=ref<PlantSourceView|null>(null),notice=ref(''),error=ref(''),sourceError=ref(''),loading=ref(false)
const context=computed<AgentContext>(()=>({plantId:Number(plant.value?.id||route.params.id),sampleIds:[]}))
let ctl:AbortController|null=null
function payload(value:unknown):Record<string,unknown>{if(typeof value==='string'){try{const parsed=JSON.parse(value);return parsed&&typeof parsed==='object'?parsed:{}}catch{return {raw:value}}}return value&&typeof value==='object'?value as Record<string,unknown>:{} }
function label(value:unknown):string{return value===null||value===undefined||value===''?'未提供':typeof value==='object'?JSON.stringify(value):String(value)}
const fieldLabels:Record<string,string>={scientific_name:'来源学名',accepted_name:'来源接受名',synonym_name:'来源异名',name_zh:'中文名候选（来源）',rank:'来源分类等级',authorship:'命名人',source_namespace:'数据集',kind:'测量类型',value:'标准化数值',raw_value:'原始数值',unit:'单位',basis:'计量基础',analyte:'分析物',study_id:'研究标识',sample_id:'独立样本标识'}
const traitLabels:Record<string,string>={'leaf shape':'叶形','leaf margin':'叶缘','flower colour':'花色','habit':'生长型','life form':'生活型','fruit type':'果实类型','fruit shape':'果实形状','leaf arrangement':'叶序','seed colour':'种子颜色','leaf max_ length [cm]':'叶长上界（cm）','leaf min_ length [cm]':'叶长下界（cm）','plant max_ height [m]':'株高上界（m）','plant min_ height [m]':'株高下界（m）'}
function recordFields(value:unknown):Record<string,unknown>{const n=payload(value),out:Record<string,unknown>={};for(const [key,title] of Object.entries(fieldLabels))if(n[key]!==null&&n[key]!==undefined)out[title]=n[key];if(n.traits&&typeof n.traits==='object')for(const [key,v] of Object.entries(n.traits))out[`${traitLabels[key]||key} · 来源提取`]=v;if(Array.isArray(n.classification))out['分类链 · 来源记录']=n.classification.map(x=>{const r=payload(x);return `${r.name||''} (${r.rank||''})`}).join(' → ');return out}
const observedTraits=computed(()=>{const out:{key:string;title:string;value:string;candidateId:string;confidence:string}[]=[];const seen=new Set<string>();for(const record of detail.value?.records||[]){const n=payload(record.normalized_payload);if(record.pipeline!=='MORPHOLOGY'||!n.traits||typeof n.traits!=='object')continue;for(const [key,value] of Object.entries(n.traits)){if(value===null||value===undefined||value==='')continue;const identity=key+JSON.stringify(value);if(seen.has(identity))continue;seen.add(identity);out.push({key:identity,title:traitLabels[key]||key,value:label(value),candidateId:record.id,confidence:record.knowledge_confidence||'UNRESOLVED'});if(out.length>=8)return out}}return out})
const familyRecord=computed(()=>detail.value?.taxonomy.find(t=>t.taxon_rank==='FAMILY'))
async function load(){ctl?.abort();const current=new AbortController();ctl=current;plant.value=null;node.value=null;sources.value=[];detail.value=null;error.value='';sourceError.value='';loading.value=true;try{const id=String(route.params.id),admin=route.query.scope==='admin';const [data,sourceResult,rich]=await Promise.allSettled([workbenchApi.plant(id,admin,current.signal),fetch(`/api/v1/plants/${encodeURIComponent(id)}/sources`,{credentials:'include',signal:current.signal,headers:{Accept:'application/json'}}).then(async r=>{if(!r.ok)throw Error(`来源记录暂不可用（${r.status}）`);return await r.json() as PlantSourceView}),fetch(`/api/v1/plants/${encodeURIComponent(id)}`,{signal:current.signal}).then(async r=>{if(!r.ok)throw Error();return await r.json() as Record<string,unknown>})]);if(ctl!==current)return;if(data.status==='fulfilled'){plant.value=data.value.plant as PlantRich;node.value=data.value.graphNodeId;sources.value=data.value.sources;notice.value=data.value.notice}else throw data.reason;if(rich.status==='fulfilled')plant.value={...plant.value,...rich.value} as PlantRich;if(sourceResult.status==='fulfilled')detail.value=sourceResult.value;else sourceError.value=(sourceResult.reason as Error).message}catch(e){if((e as Error).name!=='AbortError'&&ctl===current)error.value=(e as Error).message}finally{if(ctl===current)loading.value=false}}
watch([()=>route.params.id,()=>route.query.scope],load);onMounted(load);onUnmounted(()=>ctl?.abort())
</script>


<template><main class="plant-record museum-plant"><div class="plant-record__back"><RouterLink to="/explore">← 回到植物画廊</RouterLink></div><StateNotice v-if="loading" title="正在翻开这株植物的图鉴…"/><StateNotice v-if="error" tone="error" title="这一页暂时无法打开"><p>{{error}}</p><RouterLink to="/explore">回画廊，认识另一株植物 →</RouterLink></StateNotice><template v-if="plant">
<section class="plant-hero"><div class="plant-hero__image"><PlantMediaGallery :name="plant.scientificName" :plant-id="Number(plant.id)"/></div><div class="plant-hero__copy"><p class="museum-eyebrow">A PAGE FROM NATURE / 植物图鉴</p><h1>{{plant.nameZh||plant.scientificName}}</h1><p class="plant-hero__latin">{{plant.scientificName}}</p><p class="plant-editorial-intro">{{plant.morphology|| (plant.genusNameLatin?`这份资料以 ${plant.genusNameLatin} 为属名记录。让我们从名字开始，沿着真实的资料，慢慢走近它。`:'一个名字，一份真实的来源。沿着下面的记录，慢慢认识这株植物。')}}</p><p class="plant-quiet-state"><StatusIndicator :state="String(plant.identityState??'')"/><span>名称与属性按各自来源理解</span></p><a class="museum-inline-link" href="#appearance">走近一点，看它的细节 ↓</a></div></section>
<nav class="plant-record__anchors" aria-label="植物记录分区"><a href="#appearance">看见细节</a><a href="#names">认识名字</a><a href="#relationships">发现联系</a><a href="#sources">知识的来处</a><a href="#research">继续深入</a></nav>
<section id="appearance" class="plant-chapter"><header><p class="museum-eyebrow">01 / LOOK A LITTLE CLOSER</p><h2>每个细节，<em>都是认识的开始。</em></h2></header><p v-if="!observedTraits.length&&!plant.morphology" class="plant-gentle-empty">这份目录还没有足够的外观描述。你仍可以欣赏授权图像、查看名字的出处；我们不把照片里的印象写成未经支持的科学特征。</p><div v-if="observedTraits.length" class="plant-trait-gallery"><article v-for="trait in observedTraits" :key="trait.key"><small>来源外观记录</small><h3>{{trait.title}}</h3><p>{{trait.value}}</p><RouterLink :to="{path:'/knowledge-graph',query:{nodeId:`candidate:${trait.candidateId}`}}">查看这一条的出处 ↗</RouterLink></article></div><p v-if="plant.morphology" class="plant-quoted-observation">{{plant.morphology}}</p><section v-if="plant.distribution" class="plant-distribution"><h3>资料里，它在哪里？</h3><p>{{plant.distribution}}</p></section><p v-if="observedTraits.length" class="museum-fineprint">特征按来源逐条呈现；资料记载和自动整理不等于人工核验。</p></section>
<section id="names" class="plant-chapter plant-name-chapter"><div><p class="museum-eyebrow">02 / A NAME, A CONNECTION</p><h2>名字，<br/><em>也是一条线索。</em></h2><p>中文名、学名与分类记录，保留资料中的表达。缺少的名字，不用想象补上。</p></div><div><div v-if="detail?.names.length" class="plant-name-list"><article v-for="(x,i) in detail.names" :key="i"><b>{{x.name_text}}</b><span>{{x.name_role==='COMMON'?'来源常用名':x.name_role==='SCIENTIFIC'?'来源学名':x.name_role==='SYNONYM'?'来源异名':'名称记录'}} · {{x.language_tag||'语言未标注'}}</span><details v-if="x.source_url?.startsWith('https://api.iflora.cn/') || x.source_url==='http://www.sp2000.org.cn/'"><summary>名称出处</summary><a :href="x.source_url" target="_blank" rel="noopener">{{x.source_url==='http://www.sp2000.org.cn/'?'SP2000 · 中国生物物种名录':'iFlora · COLChina'}} 名称元数据 ↗</a><p>{{x.source_version}} · {{x.match_method}} · {{x.confidence}}</p><p>来源分类标识 {{x.authority_taxon_id}} · 查询 {{x.queried_at}}</p><p v-if="x.name_source_sheet">工作表 {{x.name_source_sheet}} · 第 {{x.name_source_row}} 行</p><p>SHA-256 {{x.name_source_sha256}}</p></details></article></div><p v-else>尚未读取到更多名称。</p><div v-if="detail?.taxonomy.length" class="plant-taxonomy"><RouterLink v-for="t in detail.taxonomy" :key="t.id" :to="{path:'/knowledge-graph',query:{nodeId:`taxon:${t.id}`}}"><b>{{t.canonical_name}}</b><span>{{t.taxon_rank==='FAMILY'?'科':t.taxon_rank==='GENUS'?'属':t.taxon_rank==='SPECIES'?'种':'分类记录'}} · 来源记载 ↗</span></RouterLink></div></div></section>
<section id="relationships" class="plant-chapter plant-relationship-chapter"><p class="museum-eyebrow">03 / FOLLOW THE THREAD</p><h2>它与什么<em>相连？</em></h2><p>{{familyRecord?`来源分类中出现了 ${familyRecord.canonical_name}。`:'从它的名字出发，看看资料里留下的联系。'}}点开网络，沿着真实的分类与来源继续探索。</p><RouterLink class="museum-button" :to="{path:'/knowledge-graph',query:{nodeId:node||`plant:${plant.id}`}}"><UiIcon name="network"/> 看看它的真实联系 <UiIcon name="arrow"/></RouterLink></section>
<section id="sources" class="plant-chapter"><header><p class="museum-eyebrow">04 / EVERY RECORD HAS A ROOT</p><h2>这份认识，<em>有迹可循。</em></h2><p>不必一次读懂所有细节。有需要时，随时回到资料的来处。</p></header><div class="plant-source-list"><article v-for="source in sources" :key="source.sourceId"><b>{{source.displayLabel}}</b><span class="museum-fineprint">来源许可：{{source.licenseState||'未知'}} · 未获许可时不公开原文</span><details><summary>查看来源版本与文件摘要</summary><p>来源标识 {{source.sourceId}}</p><p v-if="source.sha256">SHA-256 {{source.sha256}}</p><RouterLink :to="{path:'/knowledge-graph',query:{nodeId:node||`plant:${plant.id}`}}">沿图谱查看来源定位 →</RouterLink></details></article></div><p v-if="!sources.length" class="plant-gentle-empty">这一页还未返回可公开的来源关联。</p><p v-if="sourceError">{{sourceError}}</p><details class="plant-trust-details"><summary>怎样理解这些资料的可信度？</summary><p>{{notice}}</p><StatusIndicator :state="String(plant.identityState??'')"/><StatusIndicator :state="String(plant.publicationState??'')"/><p>公开是展示范围；来源记载、机器提取和具名人工核验是不同的知识状态。图像为独立授权的图鉴插图，不是物种鉴定证据。</p></details></section>
<section id="research" class="plant-chapter plant-deep-reading"><header><p class="museum-eyebrow">05 / FOR THE CURIOUS MIND</p><h2>好奇，还可以<em>更深入。</em></h2></header><div class="plant-deep-links"><RouterLink :to="{path:'/assistant',query:{plantId:String(plant.id),question:`我想了解 ${plant.nameZh||plant.scientificName} 的名称与来源`}}"><UiIcon name="spark"/><h3>问问植序</h3><p>带着这株植物的问题，寻找有依据的回答。</p><span>登录后继续 →</span></RouterLink><RouterLink :to="{path:'/workbench',query:{plantId:String(plant.id)}}"><UiIcon name="chart"/><h3>走进科研实验台</h3><p>查看实际关联的样本、研究记录和证据；没有的数据如实留空。</p><span>登录后深入研究 →</span></RouterLink></div><details class="plant-records-drawer"><summary>展开专业资料 · {{detail?.records.length??0}} 条标准化来源记录</summary><p>{{detail?.notice}}</p><div class="plant-record-list"><article v-for="record in detail?.records.slice(0,30)||[]" :key="record.id"><header><b>{{record.pipeline}}</b><StatusIndicator :state="record.knowledge_confidence||'UNRESOLVED'"/></header><dl><template v-for="(value,key) in recordFields(record.normalized_payload)" :key="String(key)"><dt>{{key}}</dt><dd>{{label(value)}}</dd></template><dt>定位</dt><dd>{{label(record.locator)}}</dd></dl><RouterLink :to="{path:'/knowledge-graph',query:{nodeId:`candidate:${record.id}`}}">在图谱中追踪这一条 →</RouterLink><RouterLink v-if="route.query.scope==='admin'" :to="{path:'/review',query:{candidateId:record.id}}">审核台候选 ↗</RouterLink></article></div><p v-if="!detail?.records.length">尚无与这株植物精确关联的公开标准化记录。</p></details><details class="plant-records-drawer"><summary>保留研究对象，继续跨模块探索</summary><ResearchContextBar :context="context" :scope="String(route.query.scope??'')" title="当前研究对象"/></details></section>
</template></main></template>
